import re
from pathlib import Path

extract_dir = '/tmp/hwpx_work/template_contents'

print("=== Searching for {{ placeholders ===")
for fpath in Path(extract_dir).rglob('*'):
    if fpath.is_file():
        with open(fpath, 'r', encoding='utf-8') as f:
            content = f.read()
        matches = re.findall(r'\{\{[^}]+\}\}', content)
        if matches:
            print(f"{fpath.name}: {matches}")

print("\n=== Searching for { fragments (excluding xmlns/http) ===")
for fpath in Path(extract_dir).rglob('*'):
    if fpath.is_file():
        with open(fpath, 'r', encoding='utf-8') as f:
            content = f.read()
        lines = content.split('\n')
        for i, line in enumerate(lines):
            if '{' in line and 'xmlns' not in line and 'http' not in line:
                # Look for single braces that might indicate split placeholders
                if re.search(r'\{[^{]', line) or re.search(r'[^}]\}', line):
                    print(f"{fpath.name}:{i+1}: {line[:100]}")

